import {withDeepReading} from './reading-depth.js?v=20261011-nine2';
const prose=s=>`<div class="action-prose">${s}</div>`;
const fold=(q,s)=>`<details class="action-fold"><summary>${q}</summary>${prose(s)}</details>`;
const insight=s=>`<div class="action-insight"><p>${s}</p></div>`;
const steps=items=>`<dl class="thinking-steps">${items.map(([t,s])=>`<div><dt>${t}</dt><dd>${s}</dd></div>`).join('')}</dl>`;
const cite=t=>`<button type="button" class="action-cite" data-element-anchor="thinking-sources">${t} · 思想来源 ↓</button>`;
const link=(url,t)=>`<a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`;
const chapters=[
{id:'understanding',title:'让经验成为可以理解的世界',lead:'从经历一件事，走向看见它的联系、意义与可能。',body:
prose('<p>同样是一次争执，最初记住的也许只是那句刺耳的话。后来重新想起，你开始看见：两个人在回答不同的问题，一个关心事情能否完成，另一个关心自己的付出是否被看见。争执没有因此被抹去，却出现了原先未曾理解的关系。</p><p>思维让我们能够在经验中辨认、比较、联系与追问。它帮助人理解一个概念，发现一段话的前提，构想尚未存在的安排，也使已经习惯的生活重新成为可以认识的对象。</p><p>本页所说的思维，包括提问、理解、推理、反思与创造认识的活动。它可以通过语言展开，也可以借助形象、空间关系与尚未成句的领会。形成判断和方案，是其中重要的用途；为一个问题获得更深的理解，也有它自己的价值。</p><p>在三层九要素中，我们从“思维—话语—行动”的联系进入这一要素：怎样理解，怎样表达，怎样参与。这个教学位置不限制思维发生的范围。检查信念、澄清意图、探索想象、理解情绪时，思维同样在场。</p><p>随着理解加深，世界在我们眼中会出现新的区别与联系。自己曾经以为的唯一解释，可以成为若干解释之一；一个笼统的“不可能”，可以展开为尚缺哪些条件；一个熟悉的人，也可以被重新认识。</p>')+
insight('思考的收获，可以是一个更清楚的判断，也可以是一个终于被打开的问题。')+
fold('思维、念头、信念与意识，分别在说什么？','<p>可以先作一个便于阅读的区分。念头，是此刻出现的一项内容，例如一句“也许还有别的方法”；思维，是我们让内容发生联系、展开理解、形成或检查判断的活动；信念，是已经被自己不同程度地当作真实、并参与解释经验的前提。</p><p>一次思考可以产生一个念头，也可以检视早已熟悉的信念。一个偶然闪过的念头，则未必已经获得认可，更不必立刻成为对自己是谁的定义。它们相互影响，但不能只因同时出现就当作一回事。</p><p>意识的讨论更宽，还涉及感知、体验、觉知以及不同哲学体系对生命的理解。本页不把意识直接等同于脑中持续出现的语言，也不把“思维”定义成所有内在活动的总和。</p><p>这些是《三道哲学》在本页采用的工作区分。细雨、赛斯和《与神对话》对“思想”“心智”“头脑”等词有各自的语境，阅读具体段落时，仍需要回到它正在讨论什么。</p>')+
fold('没有在心里说话，也可以是在思考吗？','<p>可以。重新安排房间时，你也许先在空间中试着移动桌子；构思音乐时，先听见几个声音怎样相接；理解一张图时，先看见几部分之间的关系。此时即使没有完整句子，仍可能正在辨认与组织内容。</p><p>语言会帮助我们把这种领会展开：究竟哪里不合适，几个部分怎样关联，为什么愿意作这个选择。画图、举例、实际操作，也可以帮助尚未成句的理解逐渐清楚。</p><p>第二版研究报告所整理的赛斯第424节中译材料，讨论思想与言语的区别；《与神对话》对思想的描述也包含观念和形象。本页据此保留多种思考媒介，不把该思想背景扩大成对一切非语言体验来源的证明。</p><p>同样，一个鲜明的画面或整体感本身，还不等于已经完成判断。可以珍惜它提供的线索，再通过重述、对照与实践，看看自己到底理解了什么。不同的形式可以相互帮助。</p>')+
fold('一次思考没有形成方案，也值得吗？','<p>值得。读懂一段诗、重新理解父母的一次沉默、发现自己过去怎样使用“自由”这个词，都可能改变人与世界相处的方式，即使当天没有产生新的待办事项。</p><p>理解也可能只是把一个区别看清。例如，过去把“接纳”理解成不再要求改变，后来发现承认现状与选择改变可以同时存在。这个认识让原来互相冲突的两种愿望，有了共同存在的位置。</p><p>还有些思考出于好奇：一个故事若换一个视角会怎样，一种生活方式为什么形成，一个概念能否有另一种理解。探索的过程能够带来惊奇、欣赏与智识上的愉悦，不必每次都兑换成效率。</p><p>需要作决定时，让思考回应实际问题；愿意求知时，也给理解本身一点时间。是否有价值，可以结合它带来的认识、体验和生活联系来看，不必只看它有没有立刻产出方案。</p>')+cite('细雨 · 提问与理解；赛斯译本 · 思想与言语；本体系的概念整理')},

{id:'questions',title:'从一个更好的问题开始',lead:'问题怎样被提出，会影响什么能够进入我们的视野。',body:
prose('<p>“我为什么总是做不好？”这句话看似在寻找原因，却已经先替整个人下了判断。如果带着它继续思考，许多细节只会被拿来证明自己不行。</p><p>换成“这次卡在哪一步，哪些条件尚未具备？”思考就有了可以接近的对象。准备是否充分、任务是否清楚、协作哪里中断，都能够分别被了解。问题变得具体，经验也不再只有一种用途。</p><p>提问还能够打开原先没有考虑的方向。除了怎样更快完成，我们可以问为什么值得做；除了怎样说服对方，我们可以问双方究竟在争论什么；除了哪一项选择更有利，我们可以问它会把自己带向怎样的生活。</p><p>一个好问题不必立刻得到答案。它可以先让未知显现，让分歧有名字，让调查知道从哪里开始。愿意停在一个准确的“不知道”，常常比迅速得到一个含糊的解释更能推进理解。</p><p>细雨有关提问、学习与认知追问的文字，为这一方向提供了启发。进入自己的生活时，我们可以把它落实为一种习惯：在急着回答之前，先确认这个问题是否真正问到了眼前的事。</p>')+
fold('怎样发现一个问题已经偷偷规定了答案？','<p>可以看看，若直接回答它，需要先接受什么。“怎样让所有人都认可我？”预先接受了所有人的认可既可能又必要；“我到底哪里不值得被爱？”则把不值得当作了已经成立的前提。</p><p>发现前提之后，不必急着寻找反面的肯定句。可以把它拿出来单独讨论：所有人的标准是否一致，我为什么如此需要这份认可，一次关系受挫能否说明整个人的价值？提问由此回到尚未被证明的部分。</p><p>团队讨论也会遇到类似情况。“应该由谁为失败负责？”有时过早认定了唯一责任人；“这次结果受到哪些决定和条件影响？”则能让分工、信息与资源一起出现。调查之后仍然可能确认具体责任，开放问题并不等于取消责任。</p><p>可以尝试三次改写：把对人的整体判决改成对具体事件的询问；把唯一原因改成可以比较的解释；把必须得到某个答案改成愿意了解目前有哪些依据。这些是思考的帮助，不是要求每个问题都使用固定句式。</p>')+
fold('两个人争论很久，为什么可能没有在讨论同一件事？','<p>因为一个词可能承载不同的意思，也因为双方关心的层面不同。一个人说计划“不现实”，可能指人手不足；另一个人却把这句话听成愿景没有价值。随后一方不断谈资源，另一方不断证明梦想值得，两人便越说越远。</p><p>可以先请对方给一个具体例子，再用自己的话确认：“你是在说这个方向不值得，还是说目前的安排撑不起它？”这一步让分歧从模糊的反对，成为可以共同观看的问题。</p><p>听懂之后，仍然可以不同意。可以补充遗漏的资料，质疑推论，或承认双方的价值排序不同。理解对方的理由，会让自己的赞同与反对更有内容。</p><p>有时，讨论的收获是发现原来的两个选项都不够好。例如，把“立刻全面开展”与“完全放弃”之间的空间打开，形成阶段安排。但若资源确实只能支持一个选择，也需要如实面对取舍。对话创造新的可能，也允许真实的分歧留下。</p>')+cite('细雨 · 认知追问；本体系的对话情境')},

{id:'discovery',title:'让新的认识逐渐成形',lead:'在已有材料之间，发现还没有被看见的关系。',body:
prose('<p>思维的创造，有时从一次重新连接开始。你发现一次活动总是迟到，并非每个人都不守时，而是前一项工作结束得太晚；也可能在一段旧故事里，突然看见自己正在经历的选择。</p><p>类比让不同经验相互照见，抽象使我们从具体情境中提取关系，模型则把其中一些关系组织起来，帮助继续提问。它们让认识能够超出单个事件，同时也需要不断返回具体经验。</p><p>思想实验提供另一种空间：暂时改变一个条件，看看原来的理解会怎样变化。如果一段合作没有头衔，责任会如何分配？如果一项工作不以速度评价，哪些原先看不见的价值会出现？这些问题可以让熟悉的安排重新变得可讨论。</p><p>创造认识时，可以先让几种可能出现，再选择值得发展的线索。一个粗糙的想法也许需要画出来、说给别人听、接触更多材料，才逐渐形成自己的结构。它不必在最初出现时就已经完整。</p><p>新的理解由此既包含开放，也包含认真。我们允许发现超出原计划，也愿意检查这份发现能解释什么、遗漏什么、在哪些地方需要改变。</p>')+
fold('类比、抽象与模型，怎样帮助理解而不取代现实？','<p>假设把团队比作一支乐队。这个类比可以帮助讨论彼此倾听、不同职责和共同节奏。但团队不必总有一个指挥，也不是每项工作都事先有乐谱。类比照亮某些关系，也会遮住其他关系。</p><p>抽象，是暂时放下部分细节，提取想研究的关系。比如从几次协作中提出“交接是否清楚，会影响下一步能否开始”。随后还可以继续问：清楚包含什么，哪些任务需要不同的交接方式？</p><p>模型把这样的关系组织成一个可以使用的简化图景。它的价值，在于帮助说明、比较、预测或发现遗漏。模型不需要包含现实的每个细节，却应当交代自己的用途与适用范围。</p><p>使用时可以同时写两句话：“这个比喻帮助我看见……”以及“在这里，它开始不适用了……”。能够明确第二句话，往往会让第一句话更可靠。一个有用的模型，应当允许经验告诉我们它需要怎样修改。</p><p>细雨关于类比、抽象与模型化的讨论，是本页的思想参照。乐队情境与上述使用方式是本体系的展开，不作为原作者提出的固定训练流程。</p>')+
fold('思想实验与想象，在这里有什么联系？','<p>想象使一种可能能够被进入，思想实验则常带着一个需要澄清的问题，借助设想检查某种关系。两者可以使用同一幅画面，区别主要在当时希望了解什么。</p><p>例如，想象自己成为领导者，可以体验面对质疑时愿意活出的品质；继续问“如果没有任何人因为头衔而服从，领导还剩下什么”，就开始通过改变条件，探索领导的含义。</p><p>思想实验可以暴露一个定义的不足，让隐含前提显现，也可以帮助形成新的解释。但在设想中说得通，不等于现实中一定会发生。涉及真实人的反应、资源与效果时，还需要资料和实际经验。</p><p>可以把它做得简单：提出问题，选出一个关键条件，试着改变它，再记录哪些理解随之改变、哪些仍然成立。最后问：这次设想让我更清楚了什么，还需要到哪里继续了解？</p>')+
fold('灵感出现之后，怎样把它发展成自己的认识？','<p>先尽量保留它的原貌。一句话、一张草图、一个尚未能解释的联系，都可以先记下来。不必立即替它补上一套完整的理由，也不用因为暂时说不清就放弃。</p><p>随后选择一个入口继续发展：它回应了什么问题，与哪些经验相连，能否举出一个具体例子？再试着找一个不适用的情境，看看这个想法的范围在哪里。</p><p>有时，向别人解释会暴露空白。原先以为自己已经明白的词，问起来却很含糊；也可能在对方的追问中，发现原来最重要的部分尚未说出来。交流本身可以参与认识的形成。</p><p>随着材料增加，最初的灵感可能被完善，也可能只留下其中一小部分。允许它变化，是对发现继续负责。灵感提供出发点，后续的理解与检验使它逐渐成为可以分享、可以使用的认识。</p>')+cite('细雨 · 类比、抽象与模型化；本体系的认识练习')},
{id:'evidence',title:'看见事实、解释与前提',lead:'让一个判断的来路，逐渐变得清楚。',body:
prose('<p>收到一句“这个方案还不够成熟”，我们可能很快听见另一句话：“他不相信我的能力。”前一句是对方说出的内容，后一句是自己对它的理解。两者之间，有一段值得停下来了解的距离。</p><p>解释帮助我们组织经验。没有解释，许多事实只会散落在一起。但同一件事可以有几种解释，它们得到的支持也不相同。把解释的来路说清楚，我们才知道自己是在了解情况，还是已经替未知补上了答案。</p><p>继续向下看，还会遇到前提：我是否认为有能力的人不该受到质疑？我是否把一次表达当成对方长期的态度？有些前提来自过往经验，有些已经被检验过，有些只是太熟悉，以至于从未被拿出来讨论。</p><p>清楚的判断，可以从几个部分逐渐形成：目前知道什么，怎样得到这些信息，自己作了什么解释，还有哪些未知，以及什么对这次选择最重要。把它们分开，并不妨碍重新组织成一个整体。</p><p>我们不必等到拥有全部信息才开始思考。可以比较解释，说明不确定之处，形成暂定判断，并保留继续了解的方向。对自己知道多少保持诚实，也是一种清楚。</p>')+
fold('事实只能是看得见、拍得到的吗？','<p>并非如此。一次约定的时间、一项计算结果、一个人对自己疼痛或喜悦的陈述，都可以进入我们对事实的了解，但确认它们所需要的方法并不完全相同。</p><p>当你说“听到那句话，我很难过”，这是对自身体验的表达。尊重这份体验，不必先要求它能被摄像机拍到。不过，“所以对方一定想伤害我”已经增加了对他人意图的解释，还需要另外的依据。</p><p>同样，研究中的数据、历史材料中的记载、别人提供的证言，都需要考虑获取方式、可靠程度和适用范围。有人不同意，并不会自动使一项事实消失；很多人同意，也不自动完成证明。</p><p>因此，可以把问题从“这是事实还是假的”展开为：我们在讨论什么类型的主张，有哪些合适的依据，这些依据究竟支持到哪一步？这种区分能够让体验受到尊重，也让因果与意图的判断保持认真。</p>')+
fold('逻辑很顺，为什么结论仍可能有问题？','<p>因为推论的形式与出发的前提，是需要分别检查的部分。“所有有能力的人都不会犯错；我犯了错；所以我没有能力。”这段话的关键问题，就在于第一个前提并不成立。</p><p>另一些时候，问题出在推论本身。例如，“可靠的人会守约；他这次守约；所以他在一切事情上都可靠。”一次行为提供了一些信息，却不足以承担如此宽的结论。</p><p>还有一种情况是论证内部没有明显冲突，却遗漏了重要条件。方案在预算、人手都能到位时可行，不代表这些条件已经到位。形式清楚之后，仍要了解前提是否真实、范围是否适当。</p><p>可以顺着自己的结论往回走：它依赖什么？哪一项最不确定？如果这项不成立，结论会怎样变化？这个过程既能发现问题，也能帮助确认哪些理由经得起检查。</p><p>理性并不要求掌握世界的一切信息。资料有限时，仍然可以作比较、估计可能性、形成暂定解释。需要避免的是，让表达的肯定程度超过现有依据能够支持的程度。</p>')+
fold('价值选择也能认真讨论吗？','<p>可以。我们为什么重视自由、公平、安稳或创造，常常需要通过经历与思考逐渐了解。价值讨论可以追问一个原则的含义、它与其他原则是否相容，以及愿意承担什么后果。</p><p>例如，一份工作收入更高，另一份工作留下更多陪伴家人的时间。事实调查可以帮助了解收入、工时和发展条件，却不会自动替人完成价值排序。选择还包含自己愿意怎样生活。</p><p>可以继续问：我所说的安全具体是什么？这项选择会怎样影响相关的人？若情况对调，我是否仍认可同样的理由？我是在回应自己的重视，还是只是在躲避一次不舒服？这些问题都能让取舍更有内容。</p><p>最后仍可能有损失，也可能无法让所有价值同时得到满足。认真思考的意义，是让自己更明白为什么选择，并愿意回应选择带来的责任。它不承诺把每个两难都变成没有代价的答案。</p>')+cite('本体系 · 事实、解释、前提与价值的区分')},

{id:'collaboration',title:'让理性与直觉共同参与',lead:'让不同的认识线索，进入同一场认真的探索。',body:
prose('<p>有时，我们先感到某个地方不对，却还说不出原因；有时，一番推敲之后，原本模糊的倾向才变得清楚。认识可以从不同的地方开始，也可以在几种方式之间来回展开。</p><p>直觉可以带来一个整体印象、一种方向感或尚未成句的联系。理性的工作，则可以帮助追问它包含什么、与哪些经验相连、有没有相反的材料，以及怎样形成合适的决定。</p><p>感受也有自己的贡献。兴奋可能提醒我们正在接近重视的事，不安可能让尚未说清的顾虑浮现。继续了解这些体验，我们会更认识自己的需要、倾向与处境。</p><p>赛斯第615节对意识心智的讨论，同时保留了对内在材料的开放与检查信念的责任。这为本页提供了一种参照：让线索有机会进入，也让判断能够被认真讨论。</p><p>真正需要选择时，可以把这些材料放在一起：自己的感受、能够说明的理由、已有资料、实际条件，以及相关人的处境。任何一项都不必因为暂时不能包办全部工作，而被彻底排除。</p>')+
fold('一个强烈的直觉，应该怎样进入判断？','<p>可以先把几个问题分别放好。第一，它是什么体验？例如，一种期待、一幅画面、一句突然出现的话。第二，我怎样解释它的来源？第三，它对现实提出了什么主张？第四，我正在考虑采取什么行动？</p><p>这四个问题彼此有关，但答案并不自动相同。一次体验很鲜明，不等于对来源的解释已经成立；来源暂时说不清，也不妨碍把其中一个有价值的想法拿出来讨论。</p><p>例如，突然觉得另一种工作更适合自己，可以先了解那份工作的实际内容，联系相关的人，或在条件允许时体验一小部分任务。这样的接触能够增加对工作与自己的认识，却不能据此证明这份直觉来自某个特定意识层次。</p><p>决定还需要考虑代价、可承受的风险、责任与可调整的空间。有些事情适合逐步了解，有些事情必须在有限时间内取舍。让直觉参与，可以是认真听见它，再把它带进完整的考虑之中。</p>')+
fold('感到平静就更真实，感到害怕就不可靠吗？','<p>单凭平静或害怕，都不足以判定一项主张是否真实。熟悉的解释可以令人平静，即使它还缺少依据；真实的危险也可能使人紧张，即使这份紧张并不舒适。</p><p>体验仍然值得听见。可以问：是什么让我放松，是什么令我担心，这种感受在提醒哪一项需要或顾虑？然后再问：它涉及的外部情况，目前有哪些信息？两个问题可以分别获得回答。</p><p>对一项选择感到兴奋，也可能与自己的价值相连。可以把这种吸引力展开成具体内容：我期待创造什么，愿意承担哪些日常工作，有没有忽略某些条件？这样，感受就参与了理解，而不是被简化成一个自动判定对错的信号。</p><p>我们可以在条件允许时，为自己争取更从容的判断空间。但从容是一种支持，不是正确性的证明；紧急情境也可能真的要求及时行动。仍需要结合事情本身来判断。</p>')+
fold('怎样理解资料中“别再用头脑”的提醒？','<p>首先要看它正在回应什么。有的段落批评的是不断重复的自我辩护，有的强调直接经验，有的则对理性理解的范围提出更强的哲学限制。相似措辞未必在讨论同一件事。</p><p>细雨资料中既有对推理局限的批评，也有提问、类比、抽象与认知追问的积极运用。研究报告所收录的《与神对话》段落，还讨论感受、经验和思想在特定交流情境中的位置。不能据此直接排出适用于所有事情的“感受永远高于理性”。</p><p>这些来源之间存在真实的侧重与张力。本页不把它们处理成一套已经一致的认知等级，也不把译本中的解读与整理层全部转署为赛斯原话。</p><p>进入日常生活时，可以采用一个明确的立场：给体验以空间，也保留提问、比较和检查的能力。当反复解释已经挡住接触现实，可以先去了解、倾听或实践；当一个倾向将影响重大选择，也可以认真推敲它。需要调整的是当时的使用方式。</p>')+cite('赛斯 · 第615节；细雨与《与神对话》 · 理性和体验的不同侧重')},

{id:'automatic',title:'念头出现之后，我仍有选择',lead:'让觉察带来理解的余地，也带来回应的余地。',body:
prose('<p>有些句子几乎不用思考就会出现：“这件事肯定不行。”“别人已经走得比我远了。”也有一些自然出现的念头带来帮助：忽然记起一个约定，联想到一种方法，或看见他人不容易的地方。</p><p>自动出现，并不等于错误；经过长时间推敲，也不保证正确。更值得了解的是，这个念头正在怎样解释经验，得到什么支持，又会把自己带向什么回应。</p><p>当一个熟悉的判断开始影响重要选择，我们可以稍作停留：这句话是在描述当前情况，还是把过去的经验直接搬了过来？我是否认可它？它有没有需要补充的部分？</p><p>反思之后，可以修正，也可以确认原来的判断有理由；可以继续寻找材料，也可以暂时保留问题。觉察所打开的，是回应的空间。</p><p>我们不需要监督脑中出现的每一句话。值得培养的，是在需要的时候能够回到这里：我听见了这个念头，而我还可以选择怎样理解、表达与行动。</p>')+
fold('自动出现的念头，为什么不必立刻成为“我是谁”？','<p>因为出现一项内容，与认可它、反复依据它作决定，是不同的过程。脑中闪过一句嫉妒的话，不意味着自己的全部生活只能由嫉妒定义；想到一种慷慨的做法，也不等于这份品质已经在所有选择中实现。</p><p>可以先承认它出现了，再看看它与什么有关。也许你正在渴望被看见，也许旧有的比较方式又启动了，也许其中包含一项值得认真回应的实际不公平。理解这些联系，比立即给整个人定性更有帮助。</p><p>随后可以作出自己的回应：哪些部分有事实依据，哪些需要重新考虑，愿意怎样对待自己与他人。身份会在持续的体验、理解和选择中展开，不必被一个瞬间完成判决。</p><p>“我可以怎样回应这个念头”，因此往往比“出现这个念头证明我是怎样的人”更值得继续追问。它使认识自己与创造自己重新相连。</p>')+
fold('我是在深入思考，还是反复绕回原处？','<p>可以先问，这一次思考让什么发生了变化。变化不只意味着增加资料，也可能是原有材料被重新组织，一个问题终于问清，价值排序变得明确，或一份体验逐渐能够被理解。</p><p>因此，想了几次、用了多久，并不足以区分深入与空转。一个复杂问题可能需要反复接近，一段经历也可能需要时间消化。不要只因为尚未得到结论，就把整个过程判为无用。</p><p>但如果同样的指责或猜测持续重复，既没有更清楚，也越来越难以回到生活，可以考虑换一种方式：把问题写成一句具体的话，询问缺少的信息，找可信任的人谈谈，做一件能够提供反馈的小事，或先休息。</p><p>这些都是可选择的出口。并非每次都要再想一轮，也并非每次都必须停止。可以结合问题是否推进、身体与生活的状态，以及当下真正需要什么，来选择下一步。</p>')+
fold('道理都明白，为什么仍然难受？','<p>因为理解一句道理，与完整经历一件事，并不总在同一个时刻完成。你可能已经知道一次拒绝不能说明自身价值，却仍然会失落；也可能认同一项必要的决定，同时为失去的部分难过。</p><p>情绪可以被听见，不必先在辩论中获胜。可以说清发生了什么，自己在意什么，哪些需要尚未被回应。与此同时，仍可以检查由此产生的判断，例如“这意味着我永远不会被接受”是否得到支持。</p><p>这样，感受与解释各有被理解的位置。我们既不必用道理取消难受，也不必因为难受就认可随之出现的每个结论。思维可以帮助情绪找到更准确的语言，情绪也可以让思维看见原先遗漏的重视。</p><p>如果一份困扰持续影响生活，还可以寻求可靠的人际与专业支持。本页讨论的是理解与回应的方式，不把一套思考步骤当作必然消除痛苦的承诺。</p>')+cite('本体系 · 念头、认可与选择的区分；与06情绪的衔接')},

{id:'creation',title:'思想怎样参与现实的形成',lead:'认真讨论思想的力量，也认真说明我们正在讨论哪一种联系。',body:
prose('<p>一种理解，会改变我们接下来怎样参与生活。把质疑理解成共同完善的邀请，可能使人愿意继续说明；把同样的话理解成无法挽回的否定，则可能使对话很快结束。不同的回应，又会进入后续关系。</p><p>思想还可以经由话语被分享，经由安排与行动进入共同世界。一个新的概念可以帮助人们看见原先说不清的问题，一项设计可以成为可以使用的东西，一种被共同接受的解释也可能改变群体的做法。</p><p>细雨、赛斯与《与神对话》还从各自的意识观与创造观，提出更广的思想与实相关系。它们所讨论的，包含超出日常解释和行为影响的哲学主张。理解这些主张，需要保留各自的语境与分歧。</p><p>在自己的生活中，我们可以认真承担思想能够参与的部分：怎样理解眼前的人，愿意说出什么，如何安排下一步，得到回应后是否调整。真实世界同时包含他人的选择、共同条件以及我们尚未了解的因素。</p><p>思想的力量由此值得发展，认识的范围也值得说明。越能辨明其中的联系，越能够把创造的愿望带到具体而负责的参与之中。</p>')+
fold('“思想创造实相”，究竟在讨论哪些不同的问题？','<p>至少可以把几类讨论分开。第一，思想怎样组织自己的经验：同样一件事被放进不同理解中，可能获得不同的意义。第二，它怎样影响注意、表达与行动，并由此参与后续处境。</p><p>第三，是人与人之间的共同形成：一个想法被说明、讨论、接受或反对，进入合作、制度与实际安排。这里需要考虑其他参与者及共同条件。</p><p>还有更强的意识本体论或形而上学主张：思想、信念与物质事件之间，是否存在超出上述日常过程的创造关系。赛斯和《与神对话》的相关文本，不能只被缩写成“保持好心态”；它们确实提出了更广的世界观。</p><p>这几类问题可以相互启发，却不能仅凭前几类联系容易被观察，就认定最后一类主张已获得同等证明。同样，一项外部事件发生了，也不足以直接倒推出当事人曾有某个隐秘念头。</p><p>本页采取的表达方式是：哲学主张如实呈现，日常作用具体说明，个人练习交代可观察的对象。涉及某个真实事件的原因时，仍需按事件本身的证据来了解。不同来源中的思想模型，也不合并成一条共同确认的机制。</p>')+
fold('偶然出现的坏念头，需要被消灭吗？','<p>不需要把内在生活变成持续的念头检查。出现一幅不喜欢的画面、一句担忧或一时的愤怒，首先意味着此刻有了这样的内容。它是否被认可、是否形成持续判断、是否进入行为，还需要分别来看。</p><p>《与神对话》在报告所收录的段落中，对思想的创造力作了很强的表达。我们可以认真研究这份世界观，但不能仅据此为一次闪念与一次灾祸建立已经确认的因果关系，更不宜要求当事人以“曾经想过”为理由承担全部责任。</p><p>沃尔什后来的公开阐释也讨论共同创造，以及把外部事件全归给个人时产生的自责问题。那仍是在其整体神性世界观中的说明，并不等于现实中每件事情的原因已被查明。</p><p>更有用的入口，是回到当下可以理解与选择的部分：这份担心来自哪里，有没有需要处理的现实问题，我愿意如何回应相关的人？思想若已进入伤人的话语或行为，则具体面对那项行为与后果。责任可以落在事情上，不必扩大成对整个内在世界的惩罚。</p>')+
fold('新的认识一定先于新的行动吗？','<p>并不总是。我们有时先理解一个方向，再决定怎样做；有时则在实际参与之后，才明白一项工作意味着什么，或者发现自己原先使用的概念太简单。</p><p>例如，想了解怎样倾听，可以先读资料，也可以在下一次谈话中认真尝试复述对方的意思。实践带来的回应，会使“听懂”这个词获得新的内容。理解、话语与行动之间可以来回发生影响。</p><p>研究报告收录的《与神对话》既有强调信念与创造一致的段落，也有通过改变行动来改变思想的逆向训练。两处存在值得讨论的张力。把它们解释为不同阶段是一种读法，但不能当作原文已明确完成的调和。</p><p>在本体系的实践中，可以让行动成为了解的途径，而不要求自己先假装确信。诚实地说“我还在学习”，做与当前责任相称的尝试，观察回应，再更新理解。新的认识也可能就在这个过程中形成。</p>')+cite('细雨、赛斯与《与神对话》 · 思想与创造；本体系的分层讨论')},

{id:'practice',title:'让判断在生活中获得回应',lead:'让理解能够继续，也让需要完成的选择得到承担。',body:
prose('<p>当问题已经足够清楚，可以选择一种与它相称的下一步。为了理解一个概念，也许需要再读一段原文、找一个反例；为了决定怎样安排一次活动，则可能需要核对资源、听取参与者的需要。</p><p>把判断带回生活，可以从一次简短整理开始。我们正在问什么，现有理解建立在哪里，还缺少什么，下一步怎样获得回应？这些问题不必每次都写成完整表格，只在有帮助的时候使用。</p>')+
steps([['把问题写清','说明现在想理解什么，或需要决定什么。把对整个人的判决，落回可以了解的事情。'],['说出当前的理解','区分已有信息、自己的解释、尚未确认的前提，以及这次选择重视的价值。'],['选择合适的下一步','继续阅读、询问、尝试、作决定或暂缓，都可以有理由。结合实际代价与责任来选择。'],['让回应参与下一轮理解','预先想想什么会支持、削弱或不足以判断原来的想法。结果回来后，再看具体哪一部分需要更新。']])+
prose('<p>一次回应，可能让原来的判断更有依据，也可能带来新的问题。计划遇到困难时，可以修改安排；发现条件尚不充分时，也可以保留意见。思维由此成为能够继续生长的工作。</p><p>选择完成之后，仍然可能失望。我们能够认真考虑当时已有的信息与责任，却不能把所有结果都提前控制。回看时既要了解实际后果，也要分辨哪些原先可以知道、哪些是后来才出现的情况。</p><p class="action-practice-link"><a href="#/becoming/practice?step=thinking">带着一个真实问题，进入三层九要素练习 ↗</a></p>')+
fold('没有足够确定的时候，怎样作决定？','<p>先看决定是否真的需要现在作出，以及推迟会带来什么。等待有时能增加信息，有时会失去机会或把代价转给别人。时机本身也需要进入判断。</p><p>再看这项选择的范围与后果。可调整的小安排，可能允许先做一部分再了解；难以撤回、影响较大的决定，则值得投入更多调查、讨论与专业意见。不是所有事情都适合被包装成一个低成本试验。</p><p>如果已经了解了主要条件，却仍有不确定，可以说明自己基于什么选择、愿意承担什么，以及出现哪些新情况时会重新考虑。这个说明既帮助自己保持清楚，也帮助相关的人参与。</p><p>暂缓也可以是认真作出的决定。设置复看的时间或需要补充的信息，有时能让等待更有方向；但是否写下一张清单，并不能单独判定审慎或逃避。仍要看等待是否回应了事情的需要。</p><p>完成一个有依据的决定，不代表往后再也不会怀疑。可以给正常的不确定留位置，同时把注意力带回现在需要承担的工作。</p>')+
fold('怎样区分一次有效检验与事后的“找到了呼应”？','<p>关键是事先说明自己想了解什么，以及怎样的结果会使看法改变。若任何结果都能被解释成原判断正确，就很难从这次经历中获得真正的修正。</p><p>例如，社区阅览室想延长开放时间。当前的假设是：有一部分居民因为下班较晚，无法在原有时段使用。可以先了解需求，在资源允许时安排一次有限的试行，并提前记录想观察的情况。</p><p>值得了解的内容包括：新时段有多少实际使用者，是否真是原先无法到访的人，人员安排能否持续，以及原有服务受到什么影响。一次活动恰逢节日或宣传增加，也可能影响结果，需要一并考虑。</p><p>试行结束后，可以支持延长，可以发现需求有限，也可以因时间太短或情况特殊而暂不能判断。把没有支持原想法的结果也留下，才有机会改进安排。这个例子是本页的演示情境。</p><p>并非所有理解都需要数字或试行来检验。一段文本是否读懂，可以回到原文与语境；一项价值选择是否诚实，需要展开自己的理由与取舍。方法应当适合问题，不必把所有认识都变成同一种实验。</p>')+
fold('一个有依据的决定，为什么仍可能带来失望？','<p>因为决定发生在当时能够了解的条件下，结果则在更多因素共同参与的现实中展开。一次合作前的沟通很顺利，仍可能在长期工作中暴露分工问题；准备充分的一次活动，也可能受到突发条件影响。</p><p>这不意味着过程没有意义。可以回看：哪些信息已经具备却被忽略，哪些假设范围太大，哪些变化当时难以预见？分别了解这些部分，才能知道下次需要怎样调整。</p><p>也要看判断是否回应了真正的目标。例如，只用完成速度评价合作，可能遗漏了长期学习与关系质量。结果带来的失望，有时会帮助我们重新看清最初重视的是什么。</p><p>还有些失望来自真实的取舍。选择更多陪伴，也许确实放弃了一项机会；坚持某个原则，也许确实需要付出代价。承担这些损失，不自动说明原来的选择错误。</p><p>可以修正一个前提、一个方法或一项安排，而不把一次结果扩大成对全部能力与身份的否定。反思的价值，是让下一次参与更有认识。</p>')+cite('本体系 · 根据问题选择检验方式；研究报告中的可修正性讨论')},

{id:'return',title:'让理解保持生长',lead:'让思考成为持续认识生命的一种能力。',body:
prose('<p>思维可以在专注研究时发生，也可以在散步、交谈、阅读和认真做事时展开。重要的是，愿意让经验进入，愿意让问题变化，也愿意把新发现发展成自己的理解。</p><p>有些时候，我们需要有条理地推演；有些时候，可以暂时放下结论，听一段不同的叙述，进入一种陌生的经验。开放与检验并非只按固定顺序出现，它们可以在同一次探索中相互推动。</p><p>与他人一起思考，尤其能够带来自己独自看不见的部分。认真复述对方的意思，说清自己的理由，允许一个问题被共同改写，都是让认识继续生长的方式。</p><p>当理解准备被分享，它就走向了话语。我们需要选择怎样说，哪些地方已经清楚，哪些仍待了解，以及愿意为表达承担什么。话语也会反过来让思想变得更准确。</p><p>在三层九要素中，思维与想象、聚焦、情绪相互影响，也与话语、行动往返成环。我们不必等到拥有完美的判断才开始生活。可以带着当前的认识认真参与，再让生活继续教会自己。</p>')+
insight('我正在怎样理解这件事？还有什么，值得重新看见？')+
fold('怎样为自己留一段不急着有用的思考？','<p>可以从一个真正好奇的小问题开始：一首诗为什么让自己停下来，一种习惯怎样形成，同一个词为什么在人们口中有不同的意思。先允许这个问题存在，不必立即决定它能带来什么成果。</p><p>找一些相关材料，记下引起注意的联系，也可以画图、换一种说法，或与朋友聊一聊。若谈着谈着问题改变了，可以顺着新的方向再走一段。</p><p>不急着有用，也不意味着所有想法都无需认真。遇到事实性主张仍可以查证，发现一个概念不清楚仍可以追问。只是暂时不以是否立即产生收益，来决定探索值不值得继续。</p><p>有时最后只留下一个更好的问题，有时会形成一段新的理解，有时只是更能欣赏某种经验。这些都可以成为认识生活的一部分。</p>')+
fold('怎样知道自己真正理解了一段话？','<p>可以尝试用自己的语言说出它在回答什么，并保留原文的重要限定。不是把所有词换成同义词，而是说明其中几部分为什么这样连接。</p><p>再找一个合适的例子，以及一个不适用或可能被误用的情境。比如理解“接纳自己”，既能说明怎样承认真实感受，也能说明为什么它不自动取消对行为后果的责任。</p><p>若一时说不出来，可以先画图、比对原文、回到上下文。表达困难不必立刻被判成完全没懂，但它可以指出还有哪里值得发展。与别人讨论时，也允许对方的追问改变自己的理解。</p><p>最终，不必要求自己能复述作者的每一句话。更重要的是知道这份认识来自哪里，究竟说了什么，适用于怎样的问题，又有哪些部分自己仍然不清楚。理解因此能够被分享，也能够继续被修正。</p>')+cite('细雨 · 学习与理解；本体系的阅读与表达实践')},
];

export function thinkingPage(){return `<div class="page-shell becoming-page be-element action-page thinking-page">
<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a><span>/</span><a href="#/ren">人道</a><span>/</span><a href="#/becoming">三层九要素</a><span>/</span><span aria-current="page">思维</span></nav>
<header class="be-element-head action-head"><p class="eyebrow">实相层 / 07</p><h1>思维</h1><p class="be-element-essence">让经验生长为理解，<br>让选择获得清楚的方向。</p><p class="be-element-intro"><strong>我怎样把经验变成理解与判断？</strong><br>思维在经验之间发现联系，通过概念、问题与推演形成认识。我们既探索新的理解，也辨认它的依据与限度，让选择拥有理由，让尚未理解的生命继续向自己展开。</p></header>
<nav class="action-toc" id="thinking-contents" aria-label="思维的三条主线">${['打开认识','形成判断','回到生活'].map((t,i)=>`<div><span class="eyebrow">0${i+1} / 思维</span><h2>${t}</h2>${chapters.slice(i*3,i*3+3).map((c,j)=>`<button type="button" data-element-anchor="thinking-${c.id}"><span>0${i*3+j+1}</span>${c.title}<b aria-hidden="true">↘</b></button>`).join('')}</div>`).join('')}</nav>
<blockquote class="action-quote"><p>我正在怎样理解这件事？<br>还有什么，值得重新看见？</p><cite>《三道哲学》· 思维的一个实践入口</cite></blockquote>
${chapters.map((c,i)=>`<section class="be-element-section action-section thinking-chapter" id="thinking-${c.id}" aria-labelledby="thinking-${c.id}-title"><header><span class="eyebrow">0${i+1} / 理解与判断</span><h2 id="thinking-${c.id}-title">${c.title}</h2><p class="action-lead">${c.lead}</p></header>${withDeepReading('thinking',c.id,c.body)}<button type="button" class="action-up" data-element-anchor="thinking-contents">返回目录 ↑</button></section>`).join('')}
${sources()}
<nav class="be-element-footer" aria-label="继续阅读"><a href="#/becoming">← 返回三层九要素</a><a href="#/becoming/words">下一要素：话语 →</a></nav>
</div>`;}

function sources(){return `<section class="action-source-section" id="thinking-sources"><details class="be-source-note action-sources"><summary>思想来源、概念归属与阅读说明</summary><div class="action-source-list">
<article><h3>深化阅读与本页阐释</h3><p>深化阅读参照第二版研究报告所收《与神对话》第一卷的认识与经验讨论，以及细雨《读书心法》中理解与实践的联系。自由、负责与回读的情境由本页展开；关于灵魂认识的原有世界观，与日常认识活动的说明保持区分。</p></article><article><h3>本页的写作与核对范围</h3><p>本页参考《07思维·深度研究报告·第二版》，阅读其主体论述、案例、实践与归属附录，并补充核对赛斯第615节的相关英文片段及沃尔什2021年的公开阐释。正文以转述和《三道哲学》的组织阐释为主。报告对原书的阅读声明，不等同于本页已独立通读或逐段对校全部原著。</p><p>思维、念头与信念的工作区分，事实、解释与价值的辨认方式，以及问题、情境和练习，属于本体系的教学组织。把思维列入“实相层”，是日常实践的功能划分；思维也参与认识、想象和探索，并不只发生在行动之前。</p></article>
<article><h3>细雨资料 · 提问、理解与创造认识</h3><p>报告整理了细雨有关学习、认知追问、类比、抽象、模型化与意识创造的讨论。本页吸收其中对理解、探索和实践的启发，也保留原材料对理性局限的批评，不把这些批评全部改写成对某种思考技巧的温和提醒。</p><p>细雨资料包含赛斯中译、细雨点评及部分编辑整理。报告抽取的文本丢失了一些颜色与版式，所用A／B／C／D是依据上下文作出的归属判断，并非已经完成原版对校。部分标作细雨的索引同样存在批注或编者转引的不确定性。本页不把这些段落写成确定的逐字原话。</p><p>报告中的“三层信息处理”“辨念五步法”“七层图谱”等内容，归属尚有不同程度的限制。本页未将它们署为赛斯原话，也未将其制作成识别念头来源或意识等级的测试。</p>${link('https://xiyu.love/archives/y','《已知的实相》系列导读')}</article>
<article><h3>赛斯资料 · 思想、言语与意识心智</h3><p>本页独立查阅的《个人实相的本质》第615节英文片段，同时讨论意识心智的价值、内在与外来信息，以及检查信念的能力。本页借此说明开放与审视能够共同参与认识，不据此声称全部直觉都可靠。</p><p>无语言思想的讨论，另参考报告整理的第424节中译线索；自发性与纪律的讨论涉及第393节。这两节在本页未完成独立的英文全文对校，因此不标作已核对英文原文，也不补造印刷页码。</p><p>赛斯关于思想、信念与实相的论述包含明确的形而上学主张。本页保留其思想性质，不把日常行为影响或认知现象当作已经验证其全部创造观的证据。</p>${link('https://www.nowdictation.com/q/book%3Anopr%2Bsession%3A615%2Bmind/','第615节 · 意识心智')}${link('https://www.nowdictation.com/q/book%3Anopr%2Bsession%3A615%2Bexamine/','第615节 · 检查信念')}</article>
<article><h3>《与神对话》 · 思想的创造力与共同创造</h3><p>本页依据研究报告实际覆盖的第一卷及第二卷前部展开讨论，未把报告对未覆盖材料的概括，当作第三至第五卷的完整结论。作品中的对话陈述按其思想语境呈现，不作为可直接验证的神意或外部事件因果说明。</p><p>关于思想的创造力、信念与创造的一致，以及通过行动改变思想，报告提供了不同段落。本页保留其间的解释张力；“训练阶段／创造完成阶段”的调和只能是一种读法，不能写成原文已经明确给出的分期。</p><p>另核对沃尔什2021年9月17日的《You do not create alone》。该文在整体神性世界观中讨论共同创造，并提醒把外部事件全归于个人可能引发自责。它是作者后来的公开阐释，不能倒写为早期每一段话的原意，也不能简化成纯粹的社会合作模型。</p>${link('https://www.cwg.org/blog/091721','沃尔什 · You do not create alone')}</article>
<article><h3>练习与例子的使用</h3><p>本页的房间安排、团队沟通、乐队类比、社区阅览室等情境，是用于解释概念的演示，不是经验研究中的案例。练习可以根据实际问题选用，不要求每次思考都完整执行，也不承诺一次尝试能够验证长期结果或某种超常来源。</p><p>研究报告还参考了注意力、内在批评与修习传统的读物。本页未据这些二手整理宣称具体心理效应、发生比例或临床疗效，也未把不同传统的概念合并为一个已获实证验证的统一模型。</p><p>阅读可以保留分歧：哪些是原材料的主张，哪些是研究者的解释，哪些是《三道哲学》的重新组织，应当分别理解。真实的体验值得认真对待，具体的判断也值得继续寻找依据。</p></article>
</div></details></section>`;}
